  function ebDecodeCfg(cfg) {
    // Phase 3a fast-path: supplement-synth assigns each owned beast a
    // sidecar entry on window._enigmaSuppDecode so we can recover the real
    // (type, faction, quality) triplet even when the cfg falls outside the
    // existing Q4/Q5 encoding range (Q3 bench beasts in particular).
    if (window._enigmaSuppDecode && cfg != null) {
      var hit = window._enigmaSuppDecode[cfg];
      if (hit) return hit;
    }
    // Lynx (type 5) beasts live at cfg 81-84 (gold, faction 1-4), read from the game's
    // enigma_beast table 2026-10-02. Must run before the loop: cfg 84 would otherwise
    // decode as a quality-4 faction-1 beast.
    if (cfg >= 81 && cfg <= 84) return { type: 5, faction: cfg - 80, quality: 5 };
    for (var t = 1; t <= 9; t++) {
      for (var f = 1; f <= 4; f++) {
        var q5 = (t - 1) * 20 + f * 5;
        if (q5 === cfg) return { type: t, faction: f, quality: 5 };
        if (q5 - 1 === cfg) return { type: t, faction: f, quality: 4 };
      }
    }
    return { type: 0, faction: 0, quality: 5 };
  }

